from __future__ import annotations

def finite_window(gap: float, cutoff: int) -> list[tuple[int, float, bool]]:
    if gap <= 0 or cutoff < 1: raise ValueError("positive gap and cutoff required")
    epsilon = gap / (cutoff + 1)
    return [(n, n * epsilon, n * epsilon < gap) for n in range(cutoff + 2)]

if __name__ == "__main__":
    for row in finite_window(1.0, 12): print(row)

from __future__ import annotations

def in_truncated_ray(z: float, x: float, epsilon: float, cutoff: int) -> bool:
    return any(z < x + n * epsilon for n in range(cutoff + 1))

if __name__ == "__main__":
    x, y, cutoff = 2.0, 5.0, 10
    epsilon = (y-x)/(cutoff+1)
    for z in (1.5, x, 3.0, y, 5.5): print(z, in_truncated_ray(z,x,epsilon,cutoff))

from __future__ import annotations
import math

def first_crossing(gap: float, epsilon: float) -> int:
    if gap <= 0 or epsilon <= 0: raise ValueError("positive inputs required")
    return math.ceil(gap / epsilon)

if __name__ == "__main__":
    for e in (0.2, 0.05, 0.001): print(e, first_crossing(1.0,e))

